INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7695362, 1261627, 4008, '<td valign="top">Beautiful lady and beautiful light from the left to bring out the shape of her body. I think the picture could have done with some reflection from the right-front, so from the right of the photographer, to fill in some shadow, or alternatively some reduction of the strenght of the light that is coming from the right already, especially on her face. The eyes are very dark and the current light coming from two directions does not accentuate the shape of her face in a great way. Also I don''t see this as a low-contrast picture. If you ignore the black background, the histogram show a fairly even distribution of tones across 3/4 of the total spectrum. In low contrast I expect a narrow band of tones.</td>', 'Beautiful lady and beautiful light from the left to bring out the shape of her body. I think the picture could have done with some reflection from the right-front, so from the right of the photographer, to fill in some shadow, or alternatively some reduction of the strenght of the light that is coming from the right already, especially on her face. The eyes are very dark and the current light coming from two directions does not accentuate the shape of her face in a great way. Also I don''t see this as a low-contrast picture. If you ignore the black background, the histogram show a fairly even distribution of tones across 3/4 of the total spectrum. In low contrast I expect a narrow band of tones.', '2021-06-02 08:21:27.000000', NULL, 1),
(7695363, 1261920, 4008, '<td valign="top">Beautiful but is it low contrast? I don''t think so. The histogram shows a wide distribution of tones across the total spectrum, skewed towards the dark tones. I would expect a narrow band of tones. The beauty here is caused by the contrast between highlight and shadow and the edges in between.</td>', 'Beautiful but is it low contrast? I don''t think so. The histogram shows a wide distribution of tones across the total spectrum, skewed towards the dark tones. I would expect a narrow band of tones. The beauty here is caused by the contrast between highlight and shadow and the edges in between.', '2021-06-02 08:25:38.000000', NULL, 1),
(7695373, 1261745, 4008, '<td valign="top">Beautiful but not low contrast. The picture is so beautiful especially because of the contrasts between the shadows and highlights caused by the low light. The histogram shows a wide distribution of tones, except for real black, and with a dent in the middle. You can see the bulk of the pixels widely distributed around the 1/4 and the 3/4 mark, which is exactly the contrast I already mentioned. In low contrast I expect to see a single narrow band, certainly not covering more than half of the spectrum.</td>', 'Beautiful but not low contrast. The picture is so beautiful especially because of the contrasts between the shadows and highlights caused by the low light. The histogram shows a wide distribution of tones, except for real black, and with a dent in the middle. You can see the bulk of the pixels widely distributed around the 1/4 and the 3/4 mark, which is exactly the contrast I already mentioned. In low contrast I expect to see a single narrow band, certainly not covering more than half of the spectrum.', '2021-06-02 09:01:53.000000', NULL, 1),
(7695374, 1261925, 4008, '<td valign="top">Nice tranquil scene, but quite high contrast with tones covering 3/4 of the total spectrum in the histogram. It is the contrast between window and table top versus the rest of the room that creates the atmosphere.</td>', 'Nice tranquil scene, but quite high contrast with tones covering 3/4 of the total spectrum in the histogram. It is the contrast between window and table top versus the rest of the room that creates the atmosphere.', '2021-06-02 09:04:57.000000', NULL, 1),
(7695375, 1261667, 4008, '<td valign="top">Lovely green colors but not low contrast in my view. Tones are distributed across 3/4 of the tonal spectrum in the histogram.</td>', 'Lovely green colors but not low contrast in my view. Tones are distributed across 3/4 of the tonal spectrum in the histogram.', '2021-06-02 09:08:53.000000', NULL, 1),
(7695376, 1261929, 4008, '<td valign="top">Beautiful flower but not a low contrast picture in my view. The tones are distributed across the total spectrum in the histogram, almost in a normal distribution. I would expect a narrow band of tones.</td>', 'Beautiful flower but not a low contrast picture in my view. The tones are distributed across the total spectrum in the histogram, almost in a normal distribution. I would expect a narrow band of tones.', '2021-06-02 09:12:03.000000', NULL, 1),
(7695377, 1261774, 4008, '<td valign="top">I don''t like the effect applied and it is not low contrast in my view. The tones are evenly and widely distributed in the histogram, except for the real/almost black and real/almost white.</td>', 'I don''t like the effect applied and it is not low contrast in my view. The tones are evenly and widely distributed in the histogram, except for the real/almost black and real/almost white.', '2021-06-02 09:16:28.000000', NULL, 1),
(7695378, 1261810, 4008, '<td valign="top">Severely overexposed. While this creates tones in a very narrow band (near white) it does not make it an attractive low contrast picture.</td>', 'Severely overexposed. While this creates tones in a very narrow band (near white) it does not make it an attractive low contrast picture.', '2021-06-02 09:19:27.000000', NULL, 1),
(7695380, 1261938, 4008, '<td valign="top">Great viewpoint and impressive trees, but not low contrast in my view. The shapes come out so well exactly because of the contrast between trees and sky. If you look at the histogram you also see a very wide distribution of tones across nearly the total spectrum. In low contrast I would expect a narrow band of tones. I do like the fact that the trees are not all black and still show different tones and detail.</td>', 'Great viewpoint and impressive trees, but not low contrast in my view. The shapes come out so well exactly because of the contrast between trees and sky. If you look at the histogram you also see a very wide distribution of tones across nearly the total spectrum. In low contrast I would expect a narrow band of tones. I do like the fact that the trees are not all black and still show different tones and detail.', '2021-06-02 09:44:48.000000', NULL, 1),
(7695383, 1261682, 38162, '<td valign="top">Long winded title aside, this is a terrific image and a more creative approach than the others. GL!</td>', 'Long winded title aside, this is a terrific image and a more creative approach than the others. GL!', '2021-06-02 11:36:37.000000', NULL, 1),
(7695384, 1261733, 4008, '<td valign="top">Nice colored bird. If I look at the histogram I see a very wide distribution of tones, although it does not have pure white and pure black, but that does not make it low contrast. I would expect a narrow band of tones. Also in terms of composition not very special.</td>', 'Nice colored bird. If I look at the histogram I see a very wide distribution of tones, although it does not have pure white and pure black, but that does not make it low contrast. I would expect a narrow band of tones. Also in terms of composition not very special.', '2021-06-02 12:42:42.000000', NULL, 1),
(7695385, 1261942, 4008, '<td valign="top">Even though it lacks real black and some dark tones, as well as pure white, the histogram still covers 3/4 of the total spectrum, so I don''t think it is very strong as a low contrast picture, even though if feels fairly low contrast as result of the soft colors.</td>', 'Even though it lacks real black and some dark tones, as well as pure white, the histogram still covers 3/4 of the total spectrum, so I don''t think it is very strong as a low contrast picture, even though if feels fairly low contrast as result of the soft colors.', '2021-06-02 12:45:24.000000', NULL, 1),
(7695386, 1261756, 4008, '<td valign="top">What a great cat portrait with lovely soft low contrast tones. Pin sharp on the eyes and nose, well framed and with great DOF. My pick for the blue ribbon.</td>', 'What a great cat portrait with lovely soft low contrast tones. Pin sharp on the eyes and nose, well framed and with great DOF. My pick for the blue ribbon.', '2021-06-02 13:04:59.000000', NULL, 1),
(7695387, 1261795, 4008, '<td valign="top">Very moody image and one of the few with real low contrast in this challenge.</td>', 'Very moody image and one of the few with real low contrast in this challenge.', '2021-06-02 13:05:43.000000', NULL, 1),
(7695407, 1261919, 4008, '<td valign="top">It looks like you applied a blur (?) to the picture except for the pole and a small feathered area around it? Colors are nice and soft although the total picture still covers a large part of the histogram.</td>', 'It looks like you applied a blur (?) to the picture except for the pole and a small feathered area around it? Colors are nice and soft although the total picture still covers a large part of the histogram.', '2021-06-03 05:08:57.000000', NULL, 1),
(7695408, 1261860, 4008, '<td valign="top">Nice soft portrait.</td>', 'Nice soft portrait.', '2021-06-03 05:09:41.000000', NULL, 1),
(7695455, 1261860, 107697, '<td valign="top">Adorable!</td>', 'Adorable!', '2021-06-03 18:09:12.000000', NULL, 1),
