(7695603, 1261836, 56502, '<td valign="top">Amazing colors and a somewhat serene view!</td>', 'Amazing colors and a somewhat serene view!', '2021-06-07 07:21:05.000000', NULL, 1),
(7695610, 1261931, 65234, '<td valign="top">This is a *beautiful* image but I''m not sure how low contrast it is. The background is, certainly, but the birds stand out starkly. However, on the chance that I''m misinterpreting the challenge I''m still giving you a good score. And a fave, because I really love the image.</td>', 'This is a *beautiful* image but I''m not sure how low contrast it is. The background is, certainly, but the birds stand out starkly. However, on the chance that I''m misinterpreting the challenge I''m still giving you a good score. And a fave, because I really love the image.', '2021-06-07 10:48:11.000000', NULL, 1),
(7695611, 1261749, 65234, '<td valign="top">Good on the heron to stand still for a long exposure. Looks like he''s in a little oasis of calm, and the soft tones emphasize that.</td>', 'Good on the heron to stand still for a long exposure. Looks like he''s in a little oasis of calm, and the soft tones emphasize that.', '2021-06-07 10:49:14.000000', NULL, 1),
(7695612, 1261756, 65234, '<td valign="top">Nice! Soft, lots of detail, and low contrast. You hit the bullseye.</td>', 'Nice! Soft, lots of detail, and low contrast. You hit the bullseye.', '2021-06-07 10:49:51.000000', NULL, 1),
(7695613, 1261747, 65234, '<td valign="top">Nice composition and tones.</td>', 'Nice composition and tones.', '2021-06-07 10:50:09.000000', NULL, 1),
(7695614, 1261730, 65234, '<td valign="top">Sort of poetic to me.</td>', 'Sort of poetic to me.', '2021-06-07 10:52:46.000000', NULL, 1),
(7695615, 1261745, 65234, '<td valign="top">The blue tint really suits this.</td>', 'The blue tint really suits this.', '2021-06-07 10:53:06.000000', NULL, 1),
(7695616, 1261795, 65234, '<td valign="top">Couldn''t get much more low contrast than this. Perfect example of "shrouded in fog."</td>', 'Couldn''t get much more low contrast than this. Perfect example of "shrouded in fog."', '2021-06-07 10:55:04.000000', NULL, 1),
(7695617, 1261921, 65234, '<td valign="top">It looks angry =:-O</td>', 'It looks angry =:-O', '2021-06-07 10:55:37.000000', NULL, 1),
(7695618, 1261810, 65234, '<td valign="top">This is rather high contrast, to my eye. Not what I was expecting for this challenge. Sorry.</td>', 'This is rather high contrast, to my eye. Not what I was expecting for this challenge. Sorry.', '2021-06-07 10:56:33.000000', NULL, 1),
(7695619, 1261956, 65234, '<td valign="top">Not sure about "low contrast" here. The histogram shows the whites blown out and the midtones fairly dark, which isn''t my interpretation of the challenge intention. Sorry.</td>', 'Not sure about "low contrast" here. The histogram shows the whites blown out and the midtones fairly dark, which isn''t my interpretation of the challenge intention. Sorry.', '2021-06-07 10:59:13.000000', NULL, 1),
(7695685, 1261938, 138630, '<td valign="top">Love it.  Top two and 10 from me.</td>', 'Love it.  Top two and 10 from me.', '2021-06-08 17:08:45.000000', NULL, 1),
(7695686, 1261745, 138630, '<td valign="top">Magical.  Top two and 10 from me.</td>', 'Magical.  Top two and 10 from me.', '2021-06-08 17:09:05.000000', NULL, 1),
(7695687, 1261627, 138630, '<td valign="top">Beautifully lit and toned and a lovely model.  9</td>', 'Beautifully lit and toned and a lovely model.  9', '2021-06-08 17:09:34.000000', NULL, 1),
(7695688, 1261836, 138630, '<td valign="top">Maybe a little bright for my idea of low contrast but I love the colors and light so it gets a 9 from me anyway :)</td>', 'Maybe a little bright for my idea of low contrast but I love the colors and light so it gets a 9 from me anyway :)', '2021-06-08 17:10:30.000000', NULL, 1),
(7695689, 1261675, 138630, '<td valign="top">I love the simplicity and sophistication.</td>', 'I love the simplicity and sophistication.', '2021-06-08 17:11:00.000000', NULL, 1),
(7695690, 1261931, 138630, '<td valign="top">Pretty tones.  I would be more comfortable with a horizontal flip :)</td>', 'Pretty tones.  I would be more comfortable with a horizontal flip :)', '2021-06-08 17:11:41.000000', NULL, 1),
(7695691, 1261756, 138630, '<td valign="top">Gorgeous cat portrait with great detail.  8 - but I really miss the tips of the ears.</td>', 'Gorgeous cat portrait with great detail.  8 - but I really miss the tips of the ears.', '2021-06-08 17:12:33.000000', NULL, 1),
(7695692, 1261919, 138630, '<td valign="top">Nice mood, tones and minimalism.</td>', 'Nice mood, tones and minimalism.', '2021-06-08 17:12:57.000000', NULL, 1),
(7695693, 1261902, 138630, '<td valign="top">Such a pretty sight - and site!  I would crop that sliver of sky from the top and might even come a bit lower - to where that faint wagon track in the background disappears.</td>', 'Such a pretty sight - and site!  I would crop that sliver of sky from the top and might even come a bit lower - to where that faint wagon track in the background disappears.', '2021-06-08 17:14:51.000000', NULL, 1),
(7695694, 1261824, 138630, '<td valign="top">I like the set up - depth of field, layering, use of negative space.</td>', 'I like the set up - depth of field, layering, use of negative space.', '2021-06-08 17:15:38.000000', NULL, 1),
(7695695, 1261936, 138630, '<td valign="top">Moody for sure.  Maybe just a bit too dark for me, but I love the scene.</td>', 'Moody for sure.  Maybe just a bit too dark for me, but I love the scene.', '2021-06-08 17:16:18.000000', NULL, 1),
(7695720, 1261956, 50695, '<td valign="top">lovely effect</td>', 'lovely effect', '2021-06-09 00:31:28.000000', NULL, 1),
